import React from 'react';
import type { BffCleanupPerCompanyBreakdownDto } from '../../../services/admin/responseModel';
import styles from '../DataCleanupPage.module.css';

interface CleanupPerCompanyTableProps {
  breakdown: BffCleanupPerCompanyBreakdownDto[];
  isLinmContext?: boolean;
  onDeleteCompany?: (companyCode: string) => void;
  isExecuting?: boolean;
}

export const CleanupPerCompanyTable: React.FC<CleanupPerCompanyTableProps> = ({
  breakdown,
  isLinmContext,
  onDeleteCompany,
  isExecuting,
}) => {
  const sorted = [...breakdown].sort((a, b) => b.totalDeletableRows - a.totalDeletableRows);

  return (
    <div className={styles.perCompanyGrid}>
      {sorted.map((company) => {
        const deleteRows = company.entities
          .filter((e) => e.action === 'delete' && e.rowCount > 0)
          .sort((a, b) => a.phase - b.phase || a.label.localeCompare(b.label, 'vi'));

        return (
          <div key={company.companyCode} className={styles.perCompanyCard}>
            <div className={styles.perCompanyCardHeader}>
              <span className={styles.perCompanyCardCode}>{company.companyCode}</span>
              <div className={styles.perCompanyCardRight}>
                <span className={styles.perCompanyCardCount}>
                  {company.totalDeletableRows.toLocaleString('vi-VN')}
                </span>
                {isLinmContext && onDeleteCompany && (
                  <button
                    type="button"
                    className={styles.perCompanyDeleteBtn}
                    onClick={() => onDeleteCompany(company.companyCode)}
                    disabled={company.totalDeletableRows === 0 || isExecuting}
                    title={`Xóa dữ liệu đơn vị ${company.companyCode}`}
                  >
                    <i className="fas fa-trash-alt" />
                  </button>
                )}
              </div>
            </div>
            <table className={styles.perCompanyCardTable}>
              <thead>
                <tr>
                  <th>Loại</th>
                  <th className={styles.perCompanyCountCell}>SL</th>
                </tr>
              </thead>
              <tbody>
                {deleteRows.map((row) => (
                  <tr key={row.dbSetName}>
                    <td>{row.label}</td>
                    <td className={styles.perCompanyCountCell}>
                      {row.rowCount.toLocaleString('vi-VN')}
                    </td>
                  </tr>
                ))}
                {deleteRows.length === 0 && (
                  <tr>
                    <td colSpan={2} style={{ color: '#a0aec0', fontStyle: 'italic' }}>
                      Không có dữ liệu
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        );
      })}
    </div>
  );
};
