import React from 'react';
import styles from '../DataCleanupPage.module.css';

interface CleanupFilterBarProps {
  dateFrom: string;
  dateTo: string;
  onDateFromChange: (v: string) => void;
  onDateToChange: (v: string) => void;
  allTimeMode: boolean;
  onAllTimeModeChange: (v: boolean) => void;
  selectedVoucherTypes: string[];
  onVoucherTypesChange: (v: string[]) => void;
  availableVoucherTypes: string[];
  scanByCompany: boolean;
  onScanByCompanyChange: (v: boolean) => void;
  isLinmContext: boolean;
}

const VOUCHER_TYPE_LABELS: Record<string, string> = {
  'phieu-thu': 'Phiếu thu',
  'phieu-chi': 'Phiếu chi',
  'giay-bao-co': 'Giấy báo có',
  'giay-bao-no': 'Giấy báo nợ',
  'uy-nhiem-chi': 'Ủy nhiệm chi',
  'nhat-ky-chung': 'Bút toán (NKC)',
  'but-toan': 'Bút toán',
  'hoa-don-mua-dv': 'Hóa đơn mua DV',
  'hoa-don-mua': 'Hóa đơn mua',
  'tam-ung': 'Tạm ứng',
  'chuyen-tien-noi-bo': 'Chuyển tiền nội bộ',
  'hoa-don-ban': 'Hóa đơn bán',
};

export const CleanupFilterBar: React.FC<CleanupFilterBarProps> = ({
  dateFrom,
  dateTo,
  onDateFromChange,
  onDateToChange,
  allTimeMode,
  onAllTimeModeChange,
  selectedVoucherTypes,
  onVoucherTypesChange,
  availableVoucherTypes,
  scanByCompany,
  onScanByCompanyChange,
  isLinmContext,
}) => {
  const toggleVoucherType = (code: string) => {
    if (selectedVoucherTypes.includes(code)) {
      onVoucherTypesChange(selectedVoucherTypes.filter((c) => c !== code));
    } else {
      onVoucherTypesChange([...selectedVoucherTypes, code]);
    }
  };

  const selectAllVoucherTypes = () => {
    onVoucherTypesChange([...availableVoucherTypes]);
  };

  const clearAllVoucherTypes = () => {
    onVoucherTypesChange([]);
  };

  const allSelected = availableVoucherTypes.length > 0
    && availableVoucherTypes.every((vt) => selectedVoucherTypes.includes(vt));

  return (
    <div className={styles.filterBar}>
      <div className={styles.filterRow}>
        {/* ── Date range ── */}
        <div className={styles.filterGroup}>
          <span className={styles.filterLabel}>Thời gian</span>
          <label className={styles.voucherTypeOption}>
            <input
              type="checkbox"
              checked={allTimeMode}
              onChange={(e) => onAllTimeModeChange(e.target.checked)}
            />
            Toàn bộ thời gian
          </label>
        </div>
        {!allTimeMode && (
          <>
            <div className={styles.filterGroup}>
              <span className={styles.filterLabel}>Từ ngày</span>
              <input
                type="date"
                className={styles.filterInput}
                value={dateFrom}
                onChange={(e) => onDateFromChange(e.target.value)}
              />
            </div>
            <div className={styles.filterGroup}>
              <span className={styles.filterLabel}>Đến ngày</span>
              <input
                type="date"
                className={styles.filterInput}
                value={dateTo}
                onChange={(e) => onDateToChange(e.target.value)}
              />
            </div>
          </>
        )}

        <div className={styles.filterSeparator} />

        {/* ── Voucher type checkboxes ── */}
        <div className={styles.filterGroup}>
          <span className={styles.filterLabel}>Loại chứng từ</span>
          {availableVoucherTypes.length > 0 && (
            <div className={styles.voucherTypeActions}>
              <button
                type="button"
                className={styles.voucherTypeActionBtn}
                onClick={selectAllVoucherTypes}
                disabled={allSelected}
              >
                Chọn tất cả
              </button>
              <button
                type="button"
                className={styles.voucherTypeActionBtn}
                onClick={clearAllVoucherTypes}
                disabled={selectedVoucherTypes.length === 0}
              >
                Bỏ chọn
              </button>
            </div>
          )}
          <div className={styles.voucherTypeCheckboxes}>
            {availableVoucherTypes.length === 0 ? (
              <span style={{ fontSize: '0.85rem', color: '#a0aec0' }}>
                (Quét trước để hiển thị loại CT)
              </span>
            ) : (
              availableVoucherTypes.map((code) => (
                <label key={code} className={styles.voucherTypeOption}>
                  <input
                    type="checkbox"
                    checked={selectedVoucherTypes.includes(code)}
                    onChange={() => toggleVoucherType(code)}
                  />
                  {VOUCHER_TYPE_LABELS[code] ?? code}
                </label>
              ))
            )}
          </div>
        </div>

        {isLinmContext && (
          <>
            <div className={styles.filterSeparator} />
            <div className={styles.filterGroup}>
              <span className={styles.filterLabel}>Chi tiết đơn vị</span>
              <label className={styles.voucherTypeOption}>
                <input
                  type="checkbox"
                  checked={scanByCompany}
                  onChange={(e) => onScanByCompanyChange(e.target.checked)}
                />
                Hiển thị chi tiết theo từng đơn vị
              </label>
              <span style={{ fontSize: '0.8rem', color: '#718096', marginLeft: '0.5rem' }}>
                (Admin LINM luôn quét và xóa tất cả đơn vị)
              </span>
            </div>
          </>
        )}
      </div>
    </div>
  );
};
