import React from 'react';
import { jobsService } from '../../services/jobs';
import { effectiveLowWorkerPickCapacity } from './jobParallelismQueueWarning';

/** Load Low worker pick capacity từ PlatformEventing.Runtime (Admin server-config). */
export function useLowWorkerPickCapacity(): {
  capacity: number | null;
  loading: boolean;
  reload: () => void;
} {
  const [capacity, setCapacity] = React.useState<number | null>(null);
  const [loading, setLoading] = React.useState(true);

  const load = React.useCallback(() => {
    setLoading(true);
    jobsService
      .getEventingRuntimeConfig()
      .then((cfg) =>
        setCapacity(
          effectiveLowWorkerPickCapacity({
            lowWorkerInstanceCount: cfg.lowWorkerInstanceCount,
            lowWorkerAutoScaleEnabled: cfg.lowWorkerAutoScaleEnabled,
            lowWorkerInstanceCountMax: cfg.lowWorkerInstanceCountMax,
            lowClusterInstanceCount: cfg.lowClusterInstanceCount,
          }),
        ),
      )
      .catch(() => setCapacity(null))
      .finally(() => setLoading(false));
  }, []);

  React.useEffect(() => {
    load();
  }, [load]);

  return { capacity, loading, reload: load };
}
