/** Parsed `PosInboundSyncPayload` from platform event JSON (camelCase). */
export type PosInboundSyncPayloadView = {
  runId?: string;
  companyCode?: string;
  eventType?: string;
  sourceId?: string;
  action?: string;
  connectorKey?: string;
};

const POS_EVENT_TYPE_LABELS: Record<string, string> = {
  'hoa-don': 'Hóa đơn bán',
  'phieu-thu': 'Phiếu thu',
  'phieu-chi': 'Phiếu chi',
  'dm-hang-hoa': 'Danh mục hàng hóa',
  'dm-khach-hang': 'Danh mục khách hàng',
  'dm-nha-cung-cap': 'Danh mục nhà cung cấp',
};

const POS_ACTION_LABELS: Record<string, string> = {
  create: 'Tạo mới',
  update: 'Cập nhật',
  delete: 'Xóa',
};

export const labelPosInboundEventType = (code?: string | null): string => {
  if (!code) return '—';
  return POS_EVENT_TYPE_LABELS[code] ?? code;
};

export const labelPosInboundAction = (action?: string | null): string => {
  if (!action) return '—';
  const key = action.trim().toLowerCase();
  return POS_ACTION_LABELS[key] ?? action;
};

export const parsePosInboundPayload = (payloadJson?: string | null): PosInboundSyncPayloadView | null => {
  if (!payloadJson?.trim()) return null;
  try {
    const raw = JSON.parse(payloadJson) as Record<string, unknown>;
    return {
      runId: typeof raw.runId === 'string' ? raw.runId : undefined,
      companyCode: typeof raw.companyCode === 'string' ? raw.companyCode : undefined,
      eventType: typeof raw.eventType === 'string' ? raw.eventType : undefined,
      sourceId: typeof raw.sourceId === 'string' ? raw.sourceId : undefined,
      action: typeof raw.action === 'string' ? raw.action : undefined,
      connectorKey: typeof raw.connectorKey === 'string' ? raw.connectorKey : undefined,
    };
  } catch {
    return null;
  }
};

export const formatPosInboundPayloadJson = (payloadJson?: string | null): string => {
  if (!payloadJson?.trim()) return '';
  try {
    return JSON.stringify(JSON.parse(payloadJson), null, 2);
  } catch {
    return payloadJson;
  }
};
