import React from 'react';
import { useLocation, useNavigate, useSearchParams } from 'react-router-dom';
import { InAppLink } from '../../router/InAppLink';
import { useNavTitle } from '@linm-soft-org/linm-web-common-components';
import { Button, Pagination, TableCard } from '../../ui';
import {
  jobsService,
  type DataSyncCheckpointItem,
  type DataSyncRunDetail,
  type DataSyncRunListItem,
} from '../../services/jobs';
import { useAppToast } from '@linm-soft-org/linm-web-common-components';
import JobsListToolbar from './JobsListToolbar';
import { JobExternalSyncRunDetailPanel } from './components/JobExternalSyncRunDetailPanel';
import { ExternalSyncRunOrchestrationSkeleton } from './components/ExternalSyncRunOrchestrationSkeleton';
import { filterBySearchQuery } from './jobsListFilterUtils';
import {
  buildErrorMessageMap,
  connectorLabel,
  formatCheckpointSummaryHint,
  formatExternalRunStatsLine,
  formatExternalRunCompanyLabel,
  resolveExternalRunDisplayStatus,
  resolveExternalRunListDisplayStatus,
  runDetailToListItem,
} from './externalSyncRunDisplay';
import { ExternalSyncCheckpointErrorModal, truncateExternalErrorPreview } from './components/ExternalSyncCheckpointErrorModal';
import AccountingPostControlsPanel, { useAccountingPostControls } from './AccountingPostControlsPanel';
import { useLowWorkerPickCapacity } from './useLowWorkerPickCapacity';
import ExternalSyncAutoRefreshPanel from './ExternalSyncAutoRefreshPanel';
import { useExternalSyncAutoRefreshSettings } from './useExternalSyncAutoRefreshSettings';
import MissingLedgerRepostReviewPanel from './MissingLedgerRepostReviewPanel';
import ExternalSyncActionNav from './ExternalSyncActionNav';
import ExternalSyncLegacyCashPanel from './views/ExternalSyncLegacyCashPanel';
import ExternalSyncLegacyInvoicePanel from './views/ExternalSyncLegacyInvoicePanel';
import ExternalSyncVatRefillPanel from './views/ExternalSyncVatRefillPanel';
import {
  EXTERNAL_SYNC_JOB_VIEW_META,
  externalSyncRunHref,
  filterRunsForView,
  matchesExternalSyncJobView,
  resolveExternalSyncJobView,
  resolveViewFromRun,
} from './externalSyncJobTypes';
import {
  canRetryExternalSyncRun,
  canStopExternalSyncRun,
  displayCheckpointStatus,
  displayExternalRunStatus,
  incompleteExternalCheckpointCount,
  isExternalSyncRunActive,
  jobStatusColor,
} from './jobStatusDisplay';
import styles from './JobInternalPage.module.css';
import { navigateInAppPath } from '../../router/navigateInAppPath';

const RUNS_PAGE_SIZE = 20;
const CHECKPOINT_PAGE_SIZE = 50;

const formatDate = (iso: string) => new Date(iso).toLocaleString('vi-VN');

const ExternalSyncRunsPage: React.FC = () => {
  const { pathname } = useLocation();
  const navigate = useNavigate();
  const view = resolveExternalSyncJobView(pathname);
  const viewMeta = EXTERNAL_SYNC_JOB_VIEW_META[view];
  useNavTitle(view === 'sync' ? 'Theo dõi sync ngoài (REVA FM)' : viewMeta.title);
  const toast = useAppToast();
  const [searchParams] = useSearchParams();
  const runsSectionRef = React.useRef<HTMLDivElement>(null);

  const [runs, setRuns] = React.useState<DataSyncRunListItem[]>([]);
  const [runsTotal, setRunsTotal] = React.useState(0);
  const [runsPage, setRunsPage] = React.useState(1);
  const [runSearchQuery, setRunSearchQuery] = React.useState('');
  const [selectedRunId, setSelectedRunId] = React.useState<string | null>(searchParams.get('runId'));
  const [runDetail, setRunDetail] = React.useState<DataSyncRunDetail | null>(null);
  const [checkpoints, setCheckpoints] = React.useState<DataSyncCheckpointItem[]>([]);
  const [checkpointsTotal, setCheckpointsTotal] = React.useState(0);
  const [checkpointPage, setCheckpointPage] = React.useState(1);
  const [checkpointStatus, setCheckpointStatus] = React.useState('');
  const [checkpointSearchDraft, setCheckpointSearchDraft] = React.useState('');
  const [checkpointSearchApplied, setCheckpointSearchApplied] = React.useState('');
  const [loadingRuns, setLoadingRuns] = React.useState(true);
  const [loadingDetail, setLoadingDetail] = React.useState(false);
  const [loadingCheckpoints, setLoadingCheckpoints] = React.useState(false);
  const [checkpointLoadError, setCheckpointLoadError] = React.useState<string | null>(null);
  const [errorModalCheckpoint, setErrorModalCheckpoint] = React.useState<DataSyncCheckpointItem | null>(null);
  const [retrying, setRetrying] = React.useState(false);
  const [stopping, setStopping] = React.useState(false);
  const [reimportingKey, setReimportingKey] = React.useState<string | null>(null);
  const postControls = useAccountingPostControls();
  const lowWorkers = useLowWorkerPickCapacity();
  const autoRefresh = useExternalSyncAutoRefreshSettings();

  const showLeaderSkeleton = Boolean(selectedRunId) && loadingDetail && !runDetail;

  const viewRuns = React.useMemo(() => filterRunsForView(runs, view), [runs, view]);

  const loadRuns = React.useCallback(
    (reconcileAll = false) => {
      setLoadingRuns(true);
      return jobsService
        .getDataSyncRuns(runsPage, RUNS_PAGE_SIZE, 'External', reconcileAll)
        .then((r) => {
          setRuns(r.items);
          setRunsTotal(r.total);
          return r.items;
        })
        .catch((e: Error) => {
          toast.error(e.message);
          return [] as DataSyncRunListItem[];
        })
        .finally(() => setLoadingRuns(false));
    },
    [runsPage, toast],
  );

  const loadDetail = React.useCallback(
    (runId: string) => {
      setLoadingDetail(true);
      return jobsService
        .getDataSyncRun(runId)
        .then(setRunDetail)
        .catch((e: Error) => {
          toast.error(e.message);
          setRunDetail(null);
        })
        .finally(() => setLoadingDetail(false));
    },
    [toast],
  );

  const loadCheckpoints = React.useCallback(
    (runId: string) => {
      setLoadingCheckpoints(true);
      setCheckpointLoadError(null);
      return jobsService
        .getRunCheckpoints(
          runId,
          checkpointPage,
          CHECKPOINT_PAGE_SIZE,
          checkpointStatus || undefined,
          checkpointSearchApplied || undefined,
        )
        .then((r) => {
          setCheckpoints(r.items);
          setCheckpointsTotal(r.total);
        })
        .catch((e: Error) => {
          setCheckpoints([]);
          setCheckpointsTotal(0);
          setCheckpointLoadError(e.message);
          toast.error(e.message);
        })
        .finally(() => setLoadingCheckpoints(false));
    },
    [checkpointPage, checkpointStatus, checkpointSearchApplied, toast],
  );

  /** Làm mới list + detail/checkpoint — reconcile ALL run External đang Running trên BE. */
  const refreshRuns = React.useCallback(() => {
    loadRuns(true).then(() => {
      if (!selectedRunId) return;
      loadDetail(selectedRunId);
      loadCheckpoints(selectedRunId);
    });
  }, [loadRuns, selectedRunId, loadDetail, loadCheckpoints]);

  const commitCheckpointSearch = React.useCallback(() => {
    const next = checkpointSearchDraft.trim();
    setCheckpointSearchApplied((prev) => {
      if (prev === next) return prev;
      setCheckpointPage(1);
      return next;
    });
  }, [checkpointSearchDraft]);

  React.useEffect(() => {
    const timer = window.setTimeout(() => {
      const next = checkpointSearchDraft.trim();
      setCheckpointSearchApplied((prev) => {
        if (prev === next) return prev;
        setCheckpointPage(1);
        return next;
      });
    }, 400);
    return () => window.clearTimeout(timer);
  }, [checkpointSearchDraft]);

  React.useEffect(() => {
    loadRuns(false);
  }, [loadRuns]);

  React.useEffect(() => {
    const fromUrl = searchParams.get('runId');
    if (fromUrl) {
      if (fromUrl !== selectedRunId) setSelectedRunId(fromUrl);
      return;
    }
    if (selectedRunId) {
      setSelectedRunId(null);
      setRunDetail(null);
      setCheckpoints([]);
    }
  }, [searchParams, selectedRunId]);

  React.useEffect(() => {
    if (!selectedRunId) {
      setRunDetail(null);
      setCheckpoints([]);
      return;
    }
    setRunDetail(null);
    loadDetail(selectedRunId);
  }, [selectedRunId, loadDetail]);

  /** Deep-link ?runId=… — chuyển sang tab đúng loại job (không chạy khi user đổi tab thủ công). */
  React.useEffect(() => {
    const fromUrl = searchParams.get('runId');
    if (!fromUrl || !runDetail || selectedRunId !== fromUrl) return;
    const listItem = runDetailToListItem(runDetail);
    const expectedView = resolveViewFromRun(listItem);
    if (expectedView === view) return;
    navigateInAppPath(externalSyncRunHref(expectedView, selectedRunId), navigate, { replace: true });
  }, [runDetail, selectedRunId, view, navigate, searchParams]);

  React.useEffect(() => {
    if (!selectedRunId) return;
    loadCheckpoints(selectedRunId);
  }, [selectedRunId, checkpointPage, checkpointStatus, checkpointSearchApplied, loadCheckpoints]);

  React.useEffect(() => {
    if (
      !autoRefresh.settings.enabled
      || autoRefresh.intervalMs <= 0
      || !selectedRunId
      || !runDetail
      || !isExternalSyncRunActive(runDetail.status, runDetail.checkpointSummary)
    ) {
      return undefined;
    }
    const timer = setInterval(() => {
      refreshRuns();
    }, autoRefresh.intervalMs);
    return () => clearInterval(timer);
  }, [
    autoRefresh.intervalMs,
    autoRefresh.settings.enabled,
    selectedRunId,
    runDetail?.status,
    runDetail?.checkpointSummary,
    refreshRuns,
  ]);

  const selectRun = (runId: string) => {
    setSelectedRunId(runId);
    setCheckpointPage(1);
    setCheckpointSearchDraft('');
    setCheckpointSearchApplied('');
    setCheckpointStatus('');
    setCheckpointLoadError(null);
    navigateInAppPath(externalSyncRunHref(view, runId), navigate);
  };

  const openRunAndScroll = React.useCallback(
    (runId: string) => {
      selectRun(runId);
      loadRuns(true).then(() => {
        window.requestAnimationFrame(() => {
          runsSectionRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        });
      });
    },
    [loadRuns],
  );

  React.useEffect(() => {
    const runId = searchParams.get('runId');
    if (!runId) return;
    window.requestAnimationFrame(() => {
      runsSectionRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    });
  }, [searchParams]);

  const handleStopExternalSync = () => {
    if (!selectedRunId || !runDetail || !canStopExternalSyncRun(runDetail.status)) return;
    const incomplete = incompleteExternalCheckpointCount(runDetail.checkpointSummary);
    const ok = window.confirm(
      `Dừng run sync này?\n\n` +
        `${incomplete.toLocaleString('vi-VN')} checkpoint Pending/Processing sẽ chuyển Failed.\n` +
        `Event đang chờ trong hàng đợi sẽ bị hủy.`,
    );
    if (!ok) return;

    setStopping(true);
    jobsService
      .stopExternalSyncRun(selectedRunId)
      .then((result) => {
        toast.success(
          `Đã dừng run — ${result.checkpointsStopped.toLocaleString('vi-VN')} checkpoint · hủy ${result.eventsCancelled.toLocaleString('vi-VN')} event chờ`,
        );
        loadDetail(selectedRunId);
        loadCheckpoints(selectedRunId);
        loadRuns(true);
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setStopping(false));
  };

  const handleRetryExternalSync = () => {
    if (!selectedRunId || !runDetail) return;
    if (!canRetryExternalSyncRun(runDetail.status, runDetail.checkpointSummary)) return;

    setRetrying(true);
    jobsService
      .retryExternalSyncRun(selectedRunId)
      .then((result) => {
        toast.success(
          `Đã enqueue retry ${result.documentsEnqueued.toLocaleString('vi-VN')} chứng từ — run ${result.runId.slice(0, 8)}…`,
        );
        selectRun(result.runId);
        loadRuns(true);
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setRetrying(false));
  };

  React.useEffect(() => {
    if (selectedRunId || loadingRuns || viewRuns.length === 0 || searchParams.get('runId')) return;
    selectRun(viewRuns[0].id);
  }, [selectedRunId, loadingRuns, viewRuns, searchParams, view]);

  React.useEffect(() => {
    if (!selectedRunId) return;
    if (viewRuns.some((r) => r.id === selectedRunId)) return;
    if (runDetail && matchesExternalSyncJobView(runDetailToListItem(runDetail), view)) return;
    setSelectedRunId(null);
    setRunDetail(null);
    if (searchParams.get('runId')) {
      navigateInAppPath(externalSyncRunHref(view), navigate, { replace: true });
    }
  }, [view, viewRuns, selectedRunId, runDetail, searchParams, navigate]);

  const filteredRuns = React.useMemo(
    () =>
      filterBySearchQuery(viewRuns, runSearchQuery, (r) =>
        [r.id, r.status, r.trigger, r.setsRequested.join(' '), formatDate(r.startedAtUtc), String(r.progressPercent)].join(
          ' ',
        ),
      ),
    [viewRuns, runSearchQuery],
  );

  const displayRuns = React.useMemo(() => {
    if (!selectedRunId || !runDetail || viewRuns.some((r) => r.id === selectedRunId)) {
      return filteredRuns;
    }
    const pinned = runDetailToListItem(runDetail);
    if (!matchesExternalSyncJobView(pinned, view)) {
      return filteredRuns;
    }
    const pinnedMatchesSearch = filterBySearchQuery([pinned], runSearchQuery, (r) =>
      [r.id, r.status, r.trigger, r.setsRequested.join(' '), formatDate(r.startedAtUtc), String(r.progressPercent)].join(' '),
    );
    if (pinnedMatchesSearch.length === 0) {
      return filteredRuns;
    }
    return [pinned, ...filteredRuns];
  }, [filteredRuns, selectedRunId, runDetail, viewRuns, runSearchQuery, view]);

  const checkpointFilterTotal = React.useMemo(() => {
    if (checkpointSearchApplied || checkpointStatus) {
      return checkpointsTotal;
    }
    return runDetail?.checkpointSummary?.total ?? checkpointsTotal;
  }, [runDetail?.checkpointSummary, checkpointStatus, checkpointSearchApplied, checkpointsTotal]);
  const runsPages = Math.max(1, Math.ceil(runsTotal / RUNS_PAGE_SIZE));
  const checkpointPages = Math.max(1, Math.ceil(checkpointsTotal / CHECKPOINT_PAGE_SIZE));
  const errorByDocument = React.useMemo(
    () => buildErrorMessageMap(runDetail?.errorSamples, checkpoints),
    [runDetail?.errorSamples, checkpoints],
  );

  const openErrorDetail = (checkpoint: DataSyncCheckpointItem) => {
    setErrorModalCheckpoint(checkpoint);
  };

  const canReimportCheckpoint = (checkpoint: DataSyncCheckpointItem) =>
    checkpoint.setName.startsWith('reva-fm-')
    && checkpoint.status !== 'Processing'
    && checkpoint.status !== 'Pending';

  const handleReimportCheckpoint = (checkpoint: DataSyncCheckpointItem) => {
    if (!selectedRunId || !canReimportCheckpoint(checkpoint)) return;

    const ok = window.confirm(
      `Re-import chứng từ ${checkpoint.documentKey}?\n\n` +
        'Gọi lại API REVA FM và ghi đè dữ liệu mới lên chứng từ ERP đã có ' +
        '(HĐ: master + dòng + tiền; PT: master + dòng; xóa PT thừa; unpost/repost nếu đã ghi sổ).',
    );
    if (!ok) return;

    const rowKey = `${checkpoint.setName}:${checkpoint.documentKey}`;
    setReimportingKey(rowKey);
    jobsService
      .reimportExternalDocument(selectedRunId, {
        setName: checkpoint.setName,
        documentKey: checkpoint.documentKey,
      })
      .then((result) => {
        toast.info(
          result.eventId
            ? `Đã tạo job re-import ${checkpoint.documentKey} — theo dõi checkpoint hoặc Job events (event ${result.eventId.slice(0, 8)}…).`
            : `Đã tạo job re-import ${checkpoint.documentKey} — theo dõi checkpoint bên dưới.`,
        );
        loadCheckpoints(selectedRunId);
        loadDetail(selectedRunId);
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setReimportingKey(null));
  };

  return (
    <div data-testid="external-sync-runs-page">
      <p style={{ marginBottom: 12 }}>
        <InAppLink to="/admin/jobs">← Job monitoring</InAppLink>
        {' · '}
        <InAppLink to="/admin/jobs/external-sync">Cấu hình sync REVA</InAppLink>
        {' · '}
        <InAppLink to="/admin/jobs/voucher-renumber">Đánh lại số chứng từ POS</InAppLink>
      </p>

      <p style={{ color: '#555', marginBottom: 16 }}>
        {viewMeta.listHint} Chọn tab thao tác → tạo job → theo dõi run tương ứng bên dưới.
      </p>

      <ExternalSyncActionNav />

      <AccountingPostControlsPanel
        controls={postControls.controls}
        loading={postControls.loading}
        saving={postControls.saving}
        onChange={postControls.save}
        onReload={postControls.load}
        lowWorkerPickCapacity={lowWorkers.capacity}
        loadingLowWorkers={lowWorkers.loading}
      />

      <ExternalSyncAutoRefreshPanel
        settings={autoRefresh.settings}
        onChange={autoRefresh.setSettings}
      />

      {view === 'missing-ledger' ? (
        <MissingLedgerRepostReviewPanel
          legacyRepostPaused={postControls.controls?.legacyRepostPaused}
          onRunStarted={openRunAndScroll}
        />
      ) : null}
      {view === 'legacy-cash' ? (
        <ExternalSyncLegacyCashPanel
          legacyRepostPaused={postControls.controls?.legacyRepostPaused}
          onRunStarted={openRunAndScroll}
        />
      ) : null}
      {view === 'legacy-invoice' ? (
        <ExternalSyncLegacyInvoicePanel
          legacyRepostPaused={postControls.controls?.legacyRepostPaused}
          onRunStarted={openRunAndScroll}
        />
      ) : null}
      {view === 'vat-refill' ? (
        <ExternalSyncVatRefillPanel onRunStarted={openRunAndScroll} />
      ) : null}

      <div ref={runsSectionRef} className={`${styles.shell} ${styles.shellSplitPane}`}>
        <div className={styles.splitLayout}>
          <div className={styles.splitPaneCard}>
            <TableCard
              listShell
              header={
                <div>
                  <h4 className={styles.listHeaderTitle}>Danh sách run — {viewMeta.title}</h4>
                  <p className={styles.listHint}>
                    {viewMeta.listHint} Tìm theo trạng thái, connector hoặc run id. Làm mới reconcile run External
                    đang Running.
                  </p>
                  <JobsListToolbar
                    searchQuery={runSearchQuery}
                    onSearchChange={setRunSearchQuery}
                    searchPlaceholder="Tìm run…"
                    searchTestId="external-runs-search"
                    onRefresh={refreshRuns}
                    refreshDisabled={loadingRuns}
                    totalCount={runsTotal}
                    filteredCount={displayRuns.length}
                    loading={loadingRuns}
                    itemLabel="run"
                  />
                </div>
              }
              footer={
                runsPages > 1 ? (
                  <Pagination
                    currentPage={runsPage}
                    totalPages={runsPages}
                    totalCount={runsTotal}
                    pageSize={RUNS_PAGE_SIZE}
                    itemLabel="run"
                    onPageChange={setRunsPage}
                  />
                ) : undefined
              }
            >
              {loadingRuns && runs.length === 0 ? (
                <p className={styles.gridLoading}>Đang tải…</p>
              ) : displayRuns.length === 0 ? (
                <p className={styles.gridEmpty}>
                  {runSearchQuery.trim() ? 'Không tìm thấy run phù hợp trên trang này.' : 'Chưa có run nào.'}
                </p>
              ) : (
                <ul className={styles.runList}>
                  {displayRuns.map((r) => {
                    const displayStatus = resolveExternalRunListDisplayStatus(r);
                    const companyLabel = formatExternalRunCompanyLabel(r.companyCode, r.companyName);
                    const failed = r.documentsFailed ?? 0;
                    const statsLine = formatExternalRunStatsLine(r);
                    return (
                    <li key={r.id}>
                      <button
                        type="button"
                        onClick={() => selectRun(r.id)}
                        className={`${styles.runItemBtn} ${
                          selectedRunId === r.id ? styles.runItemBtnSelected : ''
                        }`}
                      >
                        <div style={{ display: 'flex', justifyContent: 'space-between', gap: 8 }}>
                          <strong style={{ color: jobStatusColor(displayStatus) }}>
                            {r.kind === 'ExternalRetry' ? 'Retry · ' : ''}
                            {displayExternalRunStatus(displayStatus)}
                          </strong>
                          <span style={{ fontSize: 12, color: '#64748b' }}>{r.progressPercent}%</span>
                        </div>
                        {companyLabel ? (
                          <div style={{ fontSize: 12, color: '#475569', marginTop: 4 }}>
                            {companyLabel}
                          </div>
                        ) : null}
                        <div
                          style={{
                            fontSize: 12,
                            marginTop: 4,
                            color: failed > 0 ? '#b91c1c' : '#15803d',
                          }}
                        >
                          {statsLine}
                        </div>
                        <div style={{ fontSize: 13, marginTop: 4 }}>
                          {r.setsRequested.map(connectorLabel).join(', ') || '—'}
                        </div>
                        <small style={{ color: '#64748b' }}>{formatDate(r.startedAtUtc)}</small>
                        <br />
                        <small className={styles.gridSub}>{r.id.slice(0, 8)}…</small>
                      </button>
                    </li>
                    );
                  })}
                </ul>
              )}
            </TableCard>
          </div>

          <div className={styles.splitLayoutRight}>
            <div className={styles.splitPaneDetailScroll}>
              <TableCard>
                <div style={{ padding: 16 }}>
                  <div
                    style={{
                      display: 'flex',
                      flexWrap: 'wrap',
                      alignItems: 'center',
                      justifyContent: 'space-between',
                      gap: 12,
                      marginBottom: runDetail ? 12 : 0,
                    }}
                  >
                    <h4 style={{ margin: 0 }}>Chi tiết run</h4>
                    {runDetail ? (
                      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
                        {canStopExternalSyncRun(runDetail.status) ? (
                          <Button
                            type="button"
                            variant="secondary"
                            disabled={stopping || retrying}
                            onClick={handleStopExternalSync}
                            data-testid="external-sync-run-stop"
                          >
                            {stopping ? 'Đang dừng…' : 'Dừng run'}
                          </Button>
                        ) : null}
                        {canRetryExternalSyncRun(runDetail.status, runDetail.checkpointSummary) ? (
                          <Button
                            type="button"
                            variant="primary"
                            disabled={retrying || stopping}
                            onClick={handleRetryExternalSync}
                            data-testid="external-sync-run-retry"
                          >
                            {retrying
                              ? 'Đang enqueue…'
                              : `Retry chờ/lỗi (${incompleteExternalCheckpointCount(runDetail.checkpointSummary).toLocaleString('vi-VN')})`}
                          </Button>
                        ) : null}
                      </div>
                    ) : null}
                  </div>
                  {!selectedRunId ? (
                    <p style={{ color: '#64748b' }}>Chọn một run bên trái để xem tiến độ.</p>
                  ) : showLeaderSkeleton ? (
                    <ExternalSyncRunOrchestrationSkeleton />
                  ) : runDetail ? (
                    <JobExternalSyncRunDetailPanel runDetail={runDetail} />
                  ) : (
                    <p style={{ color: '#64748b' }}>Không tải được chi tiết run.</p>
                  )}
                </div>
              </TableCard>
            </div>

            <div className={styles.splitPaneCardFill}>
              <TableCard
                listShell
                className={styles.checkpointTableCard}
                header={
                  <div className={styles.checkpointHeader}>
                    <div className={styles.checkpointHeaderRow}>
                      <h4 className={styles.listHeaderTitle}>Checkpoint theo chứng từ</h4>
                      {runDetail?.checkpointSummary ? (
                        <p className={styles.checkpointSummary}>
                          {formatCheckpointSummaryHint(runDetail.checkpointSummary)}
                        </p>
                      ) : null}
                    </div>
                    {!runDetail?.checkpointSummary ? (
                      <p className={styles.listHint} style={{ margin: 0 }}>
                        Tìm theo set, mã chứng từ hoặc trạng thái.
                      </p>
                    ) : null}
                    <JobsListToolbar
                      searchQuery={checkpointSearchDraft}
                      onSearchChange={setCheckpointSearchDraft}
                      onSearch={commitCheckpointSearch}
                      searchPlaceholder="Tìm mã chứng từ, set…"
                      searchTestId="external-checkpoints-search"
                      onRefresh={
                        selectedRunId
                          ? () => {
                              loadCheckpoints(selectedRunId);
                            }
                          : undefined
                      }
                      refreshDisabled={!selectedRunId || loadingCheckpoints}
                      totalCount={checkpointFilterTotal}
                      filteredCount={checkpoints.length}
                      loading={loadingCheckpoints}
                      itemLabel="checkpoint"
                      showCountMeta={!runDetail?.checkpointSummary || Boolean(checkpointSearchApplied)}
                      extraActions={
                        <label style={{ fontSize: 13, display: 'flex', alignItems: 'center', gap: 8 }}>
                          Lọc
                          <select
                            value={checkpointStatus}
                            onChange={(e) => {
                              setCheckpointStatus(e.target.value);
                              setCheckpointPage(1);
                            }}
                            style={{ padding: '4px 8px', borderRadius: 4, border: '1px solid #cbd5e1' }}
                          >
                            <option value="">Tất cả</option>
                            <option value="Pending">Pending</option>
                            <option value="Processing">Processing</option>
                            <option value="Done">Mới import</option>
                            <option value="Updated">Cập nhật lại</option>
                            <option value="Skipped">Đã có (skip)</option>
                            <option value="Failed">Failed</option>
                          </select>
                        </label>
                      }
                    />
                  </div>
                }
                footer={
                  selectedRunId && checkpointPages > 1 ? (
                    <Pagination
                      currentPage={checkpointPage}
                      totalPages={checkpointPages}
                      totalCount={checkpointsTotal}
                      pageSize={CHECKPOINT_PAGE_SIZE}
                      itemLabel="checkpoint"
                      onPageChange={setCheckpointPage}
                    />
                  ) : undefined
                }
              >
                {!selectedRunId ? (
                  <p className={styles.gridEmpty}>Chọn run để xem checkpoint.</p>
                ) : loadingCheckpoints && checkpoints.length === 0 ? (
                  <p className={styles.gridLoading}>Đang tải checkpoint…</p>
                ) : checkpointLoadError ? (
                  <p className={styles.gridEmpty} style={{ color: '#b91c1c' }}>
                    Không tải được checkpoint: {checkpointLoadError}
                  </p>
                ) : checkpoints.length === 0 ? (
                  <p className={styles.gridEmpty}>
                    {checkpointSearchApplied
                      ? 'Không tìm thấy checkpoint phù hợp.'
                      : checkpointsTotal === 0
                        ? 'Run chưa có checkpoint — có thể search REVA chưa trả document hoặc run đang khởi tạo.'
                        : checkpointStatus
                          ? `Không có checkpoint trạng thái "${displayCheckpointStatus(checkpointStatus)}".`
                          : 'Không có checkpoint phù hợp bộ lọc.'}
                  </p>
                ) : (
                  <div className={styles.checkpointGridWrap}>
                    <table className={`${styles.gridTable} ${styles.checkpointTable}`}>
                      <thead>
                        <tr>
                          <th align="left">Loại</th>
                          <th align="left">Mã chứng từ</th>
                          <th align="left">Trạng thái</th>
                          <th align="left">Lỗi</th>
                          <th align="left">Cập nhật</th>
                          <th align="left">Thao tác</th>
                        </tr>
                      </thead>
                      <tbody>
                        {checkpoints.map((c) => {
                          const errorText =
                            c.errorMessage ??
                            errorByDocument.get(c.documentKey) ??
                            null;
                          const canViewError = c.status === 'Failed';
                          const rowReimportKey = `${c.setName}:${c.documentKey}`;
                          const isReimporting = reimportingKey === rowReimportKey;
                          return (
                          <tr key={c.id}>
                            <td>{connectorLabel(c.setName)}</td>
                            <td className={styles.gridMono}>
                              {canViewError ? (
                                <button
                                  type="button"
                                  className={styles.linkButton}
                                  onClick={() => openErrorDetail(c)}
                                  data-testid={`checkpoint-error-open-${c.documentKey}`}
                                >
                                  {c.documentKey}
                                </button>
                              ) : (
                                c.documentKey
                              )}
                            </td>
                            <td style={{ color: jobStatusColor(c.status), fontWeight: 600 }}>
                              {displayCheckpointStatus(c.status)}
                            </td>
                            <td>
                              {canViewError ? (
                                errorText ? (
                                  <button
                                    type="button"
                                    className={`${styles.linkButton} ${styles.checkpointErrorCell}`}
                                    onClick={() => openErrorDetail(c)}
                                    title={errorText}
                                  >
                                    {truncateExternalErrorPreview(errorText)}
                                  </button>
                                ) : (
                                  <button
                                    type="button"
                                    className={styles.linkButton}
                                    onClick={() => openErrorDetail(c)}
                                  >
                                    Xem chi tiết lỗi
                                  </button>
                                )
                              ) : (
                                <span style={{ color: '#64748b' }}>—</span>
                              )}
                            </td>
                            <td style={{ color: '#64748b' }}>{formatDate(c.updatedAtUtc)}</td>
                            <td className={styles.checkpointActionCell}>
                              {canReimportCheckpoint(c) ? (
                                <Button
                                  type="button"
                                  variant="secondary"
                                  disabled={Boolean(reimportingKey)}
                                  onClick={() => handleReimportCheckpoint(c)}
                                  data-testid={`checkpoint-reimport-${c.documentKey}`}
                                >
                                  {isReimporting ? 'Đang tạo job…' : 'Re-import'}
                                </Button>
                              ) : (
                                <span style={{ color: '#64748b' }}>—</span>
                              )}
                            </td>
                          </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                )}
              </TableCard>
            </div>
          </div>
        </div>
      </div>

      <ExternalSyncCheckpointErrorModal
        isOpen={errorModalCheckpoint !== null}
        runId={selectedRunId ?? ''}
        checkpoint={errorModalCheckpoint}
        onClose={() => setErrorModalCheckpoint(null)}
      />
    </div>
  );
};

export default ExternalSyncRunsPage;
