import React from 'react';
import { useAppToast } from '@linm-soft-org/linm-web-common-components';
import { Button, TableCard } from '../../../ui';
import {
  jobsService,
  type DataSyncCheckpointItem,
  type DataSyncRunDetail,
  type PlatformEventDetail,
  type PlatformEventListItem,
} from '../../../services/jobs';
import { JobEventDetailPanel } from './JobEventDetailPanel';
import { JobEventsTable } from './JobEventsTable';
import {
  JobDetailMetaGrid,
  JobDetailSection,
  formatJobDate,
  type JobDetailMetaItem,
} from './JobDetailMetaGrid';
import {
  connectorLabel,
  resolveExternalRunListDisplayStatus,
} from '../externalSyncRunDisplay';
import {
  formatPosInboundPayloadJson,
  labelPosInboundAction,
  labelPosInboundEventType,
  parsePosInboundPayload,
} from '../posInboundPayload';
import {
  displayCheckpointStatus,
  displayExternalRunStatus,
  jobStatusColor,
} from '../jobStatusDisplay';
import styles from '../JobInternalPage.module.css';

const POS_INBOUND_EVENT_TYPE = 'Pos.InboundSyncReceived';

export type PosInboundRunDetailPanelProps = {
  runId: string;
  runDetail: DataSyncRunDetail | null;
  loadingRun: boolean;
  checkpoints: DataSyncCheckpointItem[];
  checkpointsTotal: number;
  loadingCheckpoints: boolean;
  onReimportCheckpoint: (checkpoint: DataSyncCheckpointItem) => void;
  reimportingKeys: Set<string>;
};

export const PosInboundRunDetailPanel: React.FC<PosInboundRunDetailPanelProps> = ({
  runId,
  runDetail,
  loadingRun,
  checkpoints,
  checkpointsTotal,
  loadingCheckpoints,
  onReimportCheckpoint,
  reimportingKeys,
}) => {
  const toast = useAppToast();
  const [events, setEvents] = React.useState<PlatformEventListItem[]>([]);
  const [loadingEvents, setLoadingEvents] = React.useState(false);
  const [selectedEventId, setSelectedEventId] = React.useState<string | null>(null);
  const [eventDetail, setEventDetail] = React.useState<PlatformEventDetail | null>(null);
  const [loadingEventDetail, setLoadingEventDetail] = React.useState(false);

  const loadEvents = React.useCallback(() => {
    setLoadingEvents(true);
    return jobsService
      .getEvents({ page: 1, pageSize: 50, direction: 'Inbound', runId })
      .then((r) => {
        setEvents(r.items);
        return r.items;
      })
      .catch((e: Error) => {
        toast.error(e.message);
        setEvents([]);
        return [] as PlatformEventListItem[];
      })
      .finally(() => setLoadingEvents(false));
  }, [runId, toast]);

  const loadEventDetail = React.useCallback(
    (eventId: string) => {
      setLoadingEventDetail(true);
      return jobsService
        .getEvent(eventId)
        .then(setEventDetail)
        .catch((e: Error) => {
          toast.error(e.message);
          setEventDetail(null);
        })
        .finally(() => setLoadingEventDetail(false));
    },
    [toast],
  );

  React.useEffect(() => {
    setSelectedEventId(null);
    setEventDetail(null);
    void loadEvents().then((items) => {
      const primary =
        items.find((e) => e.eventType === POS_INBOUND_EVENT_TYPE) ?? items[0] ?? null;
      if (!primary) return;
      setSelectedEventId(primary.eventId);
      void loadEventDetail(primary.eventId);
    });
  }, [runId, loadEvents, loadEventDetail]);

  const selectEvent = (eventId: string) => {
    setSelectedEventId(eventId);
    void loadEventDetail(eventId);
  };

  const posPayload = parsePosInboundPayload(eventDetail?.payloadJson);
  const displayStatus = runDetail
    ? resolveExternalRunListDisplayStatus(runDetail)
    : null;

  const posDataItems: JobDetailMetaItem[] = posPayload
    ? [
        {
          label: 'Loại POS',
          value: (
            <>
              <strong>{labelPosInboundEventType(posPayload.eventType)}</strong>
              {posPayload.eventType ? (
                <div className={styles.gridSub} style={{ marginTop: 4 }}>
                  {posPayload.eventType}
                </div>
              ) : null}
            </>
          ),
        },
        { label: 'Mã nguồn (billId / id)', value: posPayload.sourceId ?? '—', mono: true },
        {
          label: 'Action',
          value: (
            <>
              <strong>{labelPosInboundAction(posPayload.action)}</strong>
              {posPayload.action ? (
                <div className={styles.gridSub} style={{ marginTop: 4 }}>
                  {posPayload.action}
                </div>
              ) : null}
            </>
          ),
        },
        {
          label: 'Connector',
          value: posPayload.connectorKey ? connectorLabel(posPayload.connectorKey) : '—',
        },
        { label: 'Company code (enqueue)', value: posPayload.companyCode ?? '—', mono: true },
      ]
    : [];

  return (
    <div data-testid="pos-inbound-run-detail">
      {loadingRun && !runDetail ? (
        <p className={styles.gridLoading}>Đang tải run…</p>
      ) : runDetail ? (
        <div className={styles.detailSummaryHero} style={{ marginBottom: 16 }}>
          <p className={styles.detailSummaryHeroTitle} style={{ color: jobStatusColor(displayStatus ?? runDetail.status) }}>
            <strong>{runDetail.setsRequested.map(connectorLabel).join(', ') || 'POS inbound'}</strong>
            {' · '}
            {displayExternalRunStatus(displayStatus ?? runDetail.status)}
          </p>
          <p className={styles.detailSummaryHeroLine}>
            Bắt đầu {formatJobDate(runDetail.startedAtUtc)}
            {runDetail.finishedAtUtc ? ` · Kết thúc ${formatJobDate(runDetail.finishedAtUtc)}` : ''}
          </p>
        </div>
      ) : null}

      {loadingEvents ? (
        <p className={styles.gridLoading}>Đang tải events…</p>
      ) : events.length === 0 ? (
        <p className={styles.gridEmpty}>Không có event Inbound cho run này.</p>
      ) : (
        <>
          <TableCard listShell header={<h4 className={styles.listHeaderTitle}>Events của run</h4>}>
            <div className={styles.eventsTableWrap}>
              <JobEventsTable
                events={events}
                selectedEventId={selectedEventId}
                onSelectEvent={selectEvent}
              />
            </div>
          </TableCard>

          {loadingEventDetail && !eventDetail ? (
            <p className={styles.gridLoading} style={{ marginTop: 16 }}>
              Đang tải chi tiết event…
            </p>
          ) : eventDetail ? (
            <div style={{ marginTop: 16 }}>
              {posPayload && eventDetail.eventType === POS_INBOUND_EVENT_TYPE ? (
                <JobDetailSection title="Dữ liệu event POS (payload)">
                  <JobDetailMetaGrid items={posDataItems} />
                  <details style={{ marginTop: 12 }}>
                    <summary style={{ cursor: 'pointer', fontWeight: 600, fontSize: 13 }}>
                      Payload JSON đầy đủ
                    </summary>
                    <pre
                      style={{
                        marginTop: 8,
                        padding: 12,
                        background: '#f8fafc',
                        borderRadius: 8,
                        fontSize: 11,
                        overflow: 'auto',
                        maxHeight: 240,
                      }}
                    >
                      {formatPosInboundPayloadJson(eventDetail.payloadJson)}
                    </pre>
                  </details>
                </JobDetailSection>
              ) : null}

              <div style={{ marginTop: 16 }}>
                <JobEventDetailPanel
                  detail={eventDetail}
                  onOpenImportRun={() => undefined}
                  onRequeued={() => void loadEvents().then(() => loadEventDetail(eventDetail.eventId))}
                />
              </div>
            </div>
          ) : selectedEventId ? (
            <p className={styles.gridEmpty} style={{ marginTop: 16 }}>
              Không tải được chi tiết event.
            </p>
          ) : null}
        </>
      )}

      {checkpoints.length > 0 ? (
        <div style={{ marginTop: 16 }}>
          <JobDetailSection title={`Checkpoint theo chứng từ (${checkpointsTotal})`}>
            {loadingCheckpoints ? (
              <p className={styles.gridLoading}>Đang tải checkpoint…</p>
            ) : (
              <div className={styles.gridWrap} style={{ maxHeight: 300, overflow: 'auto' }}>
                <table className={styles.gridTable}>
                  <thead>
                    <tr>
                      <th align="left">Loại</th>
                      <th align="left">Mã chứng từ</th>
                      <th align="left">Trạng thái</th>
                      <th align="left">Lỗi</th>
                      <th align="left">Thao tác</th>
                    </tr>
                  </thead>
                  <tbody>
                    {checkpoints.map((cp) => {
                      const rowKey = `${cp.setName}:${cp.documentKey}`;
                      const isReimporting = reimportingKeys.has(rowKey);
                      const canReimport = cp.status !== 'Processing' && cp.status !== 'Pending';
                      return (
                        <tr key={`${cp.setName}:${cp.documentKey}`}>
                          <td>{connectorLabel(cp.setName)}</td>
                          <td className={styles.gridMono}>{cp.documentKey}</td>
                          <td style={{ color: jobStatusColor(cp.status), fontWeight: 600 }}>
                            {displayCheckpointStatus(cp.status)}
                          </td>
                          <td>
                            {cp.errorMessage ? (
                              <span style={{ color: '#b91c1c', fontSize: 12 }} title={cp.errorMessage}>
                                {cp.errorMessage.length > 60
                                  ? `${cp.errorMessage.slice(0, 60)}…`
                                  : cp.errorMessage}
                              </span>
                            ) : cp.status === 'Failed' ? (
                              <span style={{ color: '#64748b', fontSize: 12 }}>Có lỗi</span>
                            ) : (
                              '—'
                            )}
                          </td>
                          <td>
                            {canReimport ? (
                              <Button
                                type="button"
                                variant="secondary"
                                disabled={isReimporting}
                                onClick={() => onReimportCheckpoint(cp)}
                                data-testid={`checkpoint-rerun-${cp.documentKey}`}
                              >
                                {isReimporting ? 'Đang chạy…' : 'Chạy lại'}
                              </Button>
                            ) : (
                              <span style={{ color: '#64748b', fontSize: 12 }}>—</span>
                            )}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </JobDetailSection>
        </div>
      ) : null}
    </div>
  );
};
